## Why This Is Asked
This question tests the ability to model stateful native components in CGO, manage memory ownership across the language boundary, and design safe streaming semantics for real-time data processing.

## Key Concepts
- Stateful C APIs with internal state maintained across function calls
- Ownership and lifecycle management of malloc'd data across CGO boundaries
- Streaming backpressure and per-chunk result handling
- Thread-safety considerations and cross-thread GC interactions
- Proper resource cleanup using finalizers

## Code Example
```c
// csv_parser.h
#ifndef CSV_PARSER_H
#define CSV_PARSER_H

#include <stdbool.h>
#include <stddef.h>

typedef struct CSVParser CSVParser;

CSVParser* csv_parser_create(const char** schema, size_t schema_len);
int csv_parser_feed(CSVParser* parser, const char* chunk, size_t len, bool is_last, char** out_json);
void csv_parser_free(CSVParser* parser);

#endif
```

```c
// csv_parser.c
#include "csv_parser.h"
#include <stdlib.h>
#include <string.h>
#include <stdio.h>

typedef struct CSVParser {
    char** schema;
    size_t schema_len;
    bool initialized;
    // internal parsing state
} CSVParser;

CSVParser* csv_parser_create(const char** schema, size_t schema_len) {
    CSVParser* parser = calloc(1, sizeof(CSVParser));
    if (!parser) return NULL;

    parser->schema = malloc(schema_len * sizeof(char*));
    for (size_t i = 0; i < schema_len; i++) {
        parser->schema[i] = strdup(schema[i]);
    }
    parser->schema_len = schema_len;
    parser->initialized = true;
    return parser;
}

int csv_parser_feed(CSVParser* parser, const char* chunk, size_t len, bool is_last, char** out_json) {
    if (!parser || !chunk || !out_json) return -1;

    // Parse chunk and generate JSON result
    // In production, this would parse CSV data according to schema
    *out_json = malloc(256);
    snprintf(*out_json, 256, "{\"records\":[], \"error\":null}");

    return is_last ? 1 : 0;  // Return 1 for last chunk
}

void csv_parser_free(CSVParser* parser) {
    if (!parser) return;
    for (size_t i = 0; i < parser->schema_len; i++) {
        free(parser->schema[i]);
    }
    free(parser->schema);
    free(parser);
}
```

```go
// csv_stream.go
package main

// #include "csv_parser.h"
// #include <stdlib.h>
import "C"
import (
    "errors"
    "runtime"
    "sync"
    "unsafe"
)

type StreamHandle struct {
    ptr *C.CSVParser
    mu  sync.RWMutex
}

func StartCSVStream(schema []string) (StreamHandle, error) {
    if len(schema) == 0 {
        return StreamHandle{}, errors.New("schema cannot be empty")
    }

    cSchema := make([]*C.char, len(schema))
    for i, s := range schema {
        cSchema[i] = C.CString(s)
    }
    defer func() {
        for _, cs := range cSchema {
            C.free(unsafe.Pointer(cs))
        }
    }()

    ptr := C.csv_parser_create(&cSchema[0], C.size_t(len(schema)))
    if ptr == nil {
        return StreamHandle{}, errors.New("failed to create parser")
    }

    handle := StreamHandle{ptr: ptr}
    runtime.SetFinalizer(&handle, func(h *StreamHandle) {
        h.mu.Lock()
        defer h.mu.Unlock()
        if h.ptr != nil {
            C.csv_parser_free(h.ptr)
            h.ptr = nil
        }
    })

    return handle, nil
}

func FeedChunk(handle StreamHandle, chunk []byte, isLast bool) (string, error) {
    handle.mu.RLock()
    defer handle.mu.RUnlock()

    if handle.ptr == nil {
        return "", errors.New("invalid stream handle")
    }

    var cChunk *C.char
    if len(chunk) > 0 {
        cChunk = C.CBytes(chunk)
        defer C.free(unsafe.Pointer(cChunk))
    }

    var cJson *C.char
    result := C.csv_parser_feed(
        handle.ptr,
        cChunk,
        C.size_t(len(chunk)),
        C.bool(isLast),
        &cJson,
    )

    if result < 0 {
        return "", errors.New("parsing error")
    }

    jsonStr := C.GoString(cJson)
    C.free(unsafe.Pointer(cJson))

    return jsonStr, nil
}
```

```go
// main.go
package main

import (
    "bufio"
    "fmt"
    "io"
    "net"
    "time"
)

const (
    ChunkSize    = 4096
    MaxChunkSize = 64 * 1024
    ReadTimeout  = 30 * time.Second
)

func main() {
    listener, err := net.Listen("tcp", ":8080")
    if err != nil {
        panic(err)
    }
    defer listener.Close()

    conn, err := listener.Accept()
    if err != nil {
        panic(err)
    }
    defer conn.Close()

    reader := bufio.NewReaderSize(conn, MaxChunkSize)
    schema := []string{"id", "name", "value"}

    stream, err := StartCSVStream(schema)
    if err != nil {
        panic(err)
    }

    buffer := make([]byte, ChunkSize)
    for {
        conn.SetReadDeadline(time.Now().Add(ReadTimeout))
        n, err := reader.Read(buffer)
        if err == io.EOF {
            break
        }
        if err != nil {
            panic(err)
        }

        isLast := n < ChunkSize
        result, err := FeedChunk(stream, buffer[:n], isLast)
        if err != nil {
            panic(err)
        }

        fmt.Println(result)

        if isLast {
            break
        }
    }
}

